"use client";
import { useLayoutEffect, useRef } from "react";
import { LayoutGroup, motion } from "motion/react";
import {
  ControlLiquid,
  ControlRoll,
  ControlStyles,
  controlVariables,
  useControlTransition,
  useControlValue,
  type ControlAppearance,
} from "./control-shared";
export interface GooeyFilterChip {
  id: string;
  label: string;
  count?: number;
  disabled?: boolean;
}
export interface GooeyFilterChipsProps extends ControlAppearance {
  items: readonly GooeyFilterChip[];
  value?: readonly string[];
  defaultValue?: readonly string[];
  onValueChange?: (
    value: string[],
  ) => void /** Supply the filtered total from your actual data. Otherwise selected item counts are summed. */;
  resultCount?: number;
  totalCount?: number;
  resultLabel?: string;
  clearLabel?: string;
  goo?: number;
  gap?: number;
}
export function GooeyFilterChips({
  items,
  value,
  defaultValue = [],
  onValueChange,
  resultCount,
  totalCount,
  resultLabel = "results",
  clearLabel = "Clear all",
  goo = 18,
  gap = 12,
  ...appearance
}: GooeyFilterChipsProps) {
  const [selected, setSelected] = useControlValue<readonly string[]>(value, defaultValue, (v) =>
    onValueChange?.([...v]),
  );
  const root = useRef<HTMLDivElement>(null);
  const focusedChip = useRef<{ id: string; node: HTMLButtonElement } | null>(null);
  useLayoutEffect(() => {
    const focused = focusedChip.current;
    if (!focused || focused.node.isConnected || document.activeElement !== document.body) return;
    const replacement = Array.from(
      root.current?.querySelectorAll<HTMLButtonElement>(".z-mc-chip") ?? [],
    ).find((node) => node.dataset.zMcLiquid === `chip-${focused.id}`);
    replacement?.focus({ preventScroll: true });
    if (!replacement) focusedChip.current = null;
  });
  const transition = useControlTransition(appearance.duration);
  const current = items.filter((i) => selected.includes(i.id));
  const remaining = items.filter((i) => !selected.includes(i.id));
  const count =
    resultCount ??
    (current.length
      ? current.reduce((n, i) => n + (i.count ?? 0), 0)
      : (totalCount ?? items.reduce((n, i) => n + (i.count ?? 0), 0)));
  const chip = (item: GooeyFilterChip) => (
    <motion.button
      layout="position"
      layoutId={`chip-${item.id}`}
      transition={transition}
      type="button"
      className="z-mc-pill z-mc-chip"
      key={item.id}
      data-z-mc-liquid={`chip-${item.id}`}
      data-selected={selected.includes(item.id)}
      aria-pressed={selected.includes(item.id)}
      disabled={item.disabled}
      onFocus={(event) => {
        focusedChip.current = { id: item.id, node: event.currentTarget };
      }}
      onBlur={() => {
        focusedChip.current = null;
      }}
      onClick={() =>
        setSelected(
          selected.includes(item.id)
            ? selected.filter((v) => v !== item.id)
            : [...selected, item.id],
        )
      }
    >
      {item.label}
    </motion.button>
  );
  return (
    <LayoutGroup>
      <ControlStyles />
      <motion.div
        layout
        ref={root}
        className={`z-mc z-mc-chips ${appearance.className ?? ""}`}
        style={{ ...controlVariables(appearance), gap }}
        transition={transition}
      >
        <ControlLiquid
          root={root}
          revision={selected.join("|") + items.map((i) => i.label).join("|")}
          duration={appearance.duration}
          goo={goo}
        />
        <button
          type="button"
          className="z-mc-chip-clear"
          disabled={!current.length}
          onClick={() => setSelected([])}
        >
          {clearLabel}
        </button>
        <motion.div
          layout
          className="z-mc-chip-tray"
          data-z-mc-liquid="tray"
          transition={transition}
        >
          <span className="z-mc-chip-count">
            <output aria-live="polite">
              <ControlRoll id={count} duration={appearance.duration}>
                {count}
              </ControlRoll>
            </output>{" "}
            <small>{resultLabel}</small>
          </span>
          {current.map(chip)}
        </motion.div>
        <div className="z-mc-chip-pool">{remaining.map(chip)}</div>
      </motion.div>
    </LayoutGroup>
  );
}
